import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    D = int(data[0])
    G = int(data[1])

    problems = []
    bonuses = []

    index = 2
    for i in range(D):
        p_i = int(data[index])
        c_i = int(data[index + 1])
        problems.append(p_i)
        bonuses.append(c_i)
        index += 2

    dp = [float('inf')] * (G + 1)
    dp[0] = 0

    for i in range(D):
        for j in range(G, -1, -1):
            for k in range(problems[i]):
                if j + 100 * (i + 1) * (k + 1) <= G:
                    dp[j + 100 * (i + 1) * (k + 1)] = min(dp[j + 100 * (i + 1) * (k + 1)], dp[j] + k + 1)
            if j + bonuses[i] <= G:
                dp[j + bonuses[i]] = min(dp[j + bonuses[i]], dp[j])

    for j in range(G, -1, -1):
        if dp[j] != float('inf'):
            print(dp[j])
            return

if __name__ == "__main__":
    main()
